#include <algorithm>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <string>
#include <unordered_set>
#include <vector>
struct Piece { std::string text; bool known; };
struct Result { std::size_t unknown; std::vector<Piece> pieces; };
bool lowercase(const std::string&s){for(unsigned char c:s)if(c<'a'||c>'z')return false;return true;}
Result respace(const std::string&text,const std::vector<std::string>&words){
 if(text.size()>200||!lowercase(text))throw std::invalid_argument("text");
 std::unordered_set<std::string> dictionary;std::size_t max_length=0;
 for(const auto&w:words){if(w.empty()||w.size()>20||!lowercase(w))throw std::invalid_argument("word");dictionary.insert(w);max_length=std::max(max_length,w.size());}
 const std::size_t n=text.size();std::vector<std::size_t>dp(n+1,0),length(n,1);std::vector<bool>known(n,false);
 for(std::size_t i=n;i>0;){--i;dp[i]=1+dp[i+1];
  for(std::size_t len=1;len<=max_length&&len<=n-i;++len){
   if(dictionary.count(text.substr(i,len))==0)continue;
   const std::size_t cost=dp[i+len];
   // 동점이면 사전 단어를 우선하고, 그중 긴 단어를 고릅니다.
   if(cost<dp[i]||(cost==dp[i]&&(!known[i]||len>length[i]))){dp[i]=cost;length[i]=len;known[i]=true;}
  }
 }
 Result result{dp[0],{}};
 for(std::size_t i=0;i<n;){result.pieces.push_back({text.substr(i,length[i]),known[i]});i+=length[i];}
 return result;
}
// 공백으로 구분된 정수 토큰 전체를 검사합니다. 1+2를 두 수로 받지 않습니다.
bool read_integer_token(long long& value) {
    std::string token;
    if (!(std::cin >> token)) return false;
    std::size_t i = (!token.empty() && (token[0] == '+' || token[0] == '-')) ? 1 : 0;
    if (i == token.size()) return false;
    for (; i < token.size(); ++i) if (token[i] < '0' || token[i] > '9') return false;
    try {
        std::size_t consumed = 0;
        value = std::stoll(token, &consumed, 10);
        return consumed == token.size();
    } catch (const std::invalid_argument&) { return false; }
      catch (const std::out_of_range&) { return false; }
}
int main(){
 // 첫 줄은 원문(빈 줄 허용), 다음은 단어 수와 공백으로 구분한 사전입니다.
 std::string text;if(!std::getline(std::cin,text))return 1;long long count=0;
 if(!read_integer_token(count)||count<0||count>1000)return 1;
 std::vector<std::string>words;
 for(long long i=0;i<count;++i){std::string w;if(!(std::cin>>w))return 1;words.push_back(w);}
 std::cin>>std::ws;if(std::cin.peek()!=std::char_traits<char>::eof())return 1;
 try{Result r=respace(text,words);std::cout<<r.unknown<<'\n';
  for(std::size_t i=0;i<r.pieces.size();++i){if(i)std::cout<<' ';if(!r.pieces[i].known)std::cout<<'[';std::cout<<r.pieces[i].text;if(!r.pieces[i].known)std::cout<<']';}std::cout<<'\n';}
 catch(const std::invalid_argument&){return 1;}return std::cout?0:1;
}
